import numpy as np

def semantic_chunks({{sentences}}, {{embed_fn}}, {{threshold}}=0.7):
    embs = [{{embed_fn}}(s) for s in {{sentences}}]
    chunks, cur = [], [{{sentences}}[0]]
    for i in range(1, len({{sentences}})):
        sim = np.dot(embs[i-1], embs[i]) / (np.linalg.norm(embs[i-1]) * np.linalg.norm(embs[i]))
        if sim < {{threshold}}: chunks.append(" ".join(cur)); cur = []
        cur.append({{sentences}}[i])
    if cur: chunks.append(" ".join(cur))
    return chunks
